-- Top-level entity for the prototype module.
--
-- Generated by bust. A thin, fixed wrapper around the sbi endpoint so the
-- module has one stable entity to instantiate. There is no user-editable region;
-- connect your logic to the to_hw/from_hw records.
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

use work.prototype_regfile_pkg.all;

entity prototype is
  generic (
    G_BASE_ADDRESS       : unsigned(31 downto 0) := 32x"0";
    G_CHECK_BASE_ADDRESS : boolean := true;
    G_MODULE_ADDR_WIDTH  : natural := C_MODULE_ADDR_WIDTH
  );
  port (
    clk     : in  std_logic;
    reset   : in  std_logic;

    cs      : in  std_logic;
    addr    : in  std_logic_vector(31 downto 0);
    rena    : in  std_logic;
    wena    : in  std_logic;
    wdata   : in  std_logic_vector(31 downto 0);
    ready   : out std_logic;
    rdata   : out std_logic_vector(31 downto 0);
    to_hw    : out t_prototype_to_hw;
    from_hw  : in  t_prototype_from_hw
  );
end entity prototype;

architecture rtl of prototype is
begin

  i_endpoint : entity work.prototype_sbi_endpoint
    generic map (
      G_BASE_ADDRESS       => G_BASE_ADDRESS,
      G_CHECK_BASE_ADDRESS => G_CHECK_BASE_ADDRESS,
      G_MODULE_ADDR_WIDTH  => G_MODULE_ADDR_WIDTH)
    port map (
      clk     => clk,
      reset   => reset,
      cs      => cs,
      addr    => addr,
      rena    => rena,
      wena    => wena,
      wdata   => wdata,
      ready   => ready,
      rdata   => rdata,
      to_hw    => to_hw,
      from_hw  => from_hw
    );

end architecture rtl;
